INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (1, 4, 0.0, 24015, "カオリ（サマー）", 0.0, 10021, 24, 0.0, "2019/07/31 12:00:00", 110501, "あうぅ～残念さ～\nマジムンに魂を\n奪われちゃったかな～？", 4, "2030/12/17 14:59:59");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (2, 4, 4.0, 24016, "カオリ（サマー）", 0.0, 10021, 24, 0.0, "2019/07/31 12:00:00", 110501, "今日は踊りのキレも悪いよ～\nゴーヤーっぽいもの食べて、元気回復さ～！", 1, "2030/12/17 14:59:59");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (3, 4, 0.0, 24017, "カオリ（サマー）", 0.0, 10021, 24, 0.0, "2019/07/31 12:00:00", 110501, "マジムンだらけで目が回るさ～！\nふらふらさ～！", 4, "2030/12/17 14:59:59");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (4, 1, 5.2, 24018, "カオリ（サマー）", 0.0, 10021, 24, 0.0, "2019/07/31 12:00:00", 110501, "なんくるない、なんくるない\n次、頑張ればいいんだよ～！\n海で泳いで\nリフレッシュするさー！", 2, "2030/12/17 14:59:59");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (5, 5, 4.2, 24019, "カオリ（サマー）", 0.0, 10021, 24, 0.0, "2019/07/31 12:00:00", 110501, "恥ずかしいところ\n見られちゃったね～\n水着？　水着のことじゃないよー？", 6, "2030/12/17 14:59:59");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (6, 2, 0.0, 24020, "カオリ（サマー）", 0.0, 10021, 24, 0.0, "2019/07/31 12:00:00", 110501, "絶好調さ～！　この調子で\n海の平和を取り戻すよ～！\n楽しい夏が待ってるさ～！", 2, "2030/12/17 14:59:59");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (7, 1, 6.4, 24021, "カオリ（サマー）", 0.0, 10021, 24, 0.0, "2019/07/31 12:00:00", 110501, "何匹で襲ってきたって\n私はマブイを落っことさないよ～！\nくしゅん！　あ……\n今のくしゃみで落っこちたかも～？", 6, "2030/12/17 14:59:59");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (8, 2, 0.0, 24022, "カオリ（サマー）", 0.0, 10021, 24, 0.0, "2019/07/31 12:00:00", 110501, "ひーやーさーさー♪\n戦いの後は、踊りを踊って\n気分スッキリさ～！", 2, "2030/12/17 14:59:59");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (9, 6, 10.08, 24023, "カオリ（サマー）", 0.0, 10021, 24, 0.0, "2019/07/31 12:00:00", 110501, "あれ～？　戦ってるうちに\n水着がどっか行っちゃった～？\nねぇキミ、どっかで見なかった～？\nなんで離れるさ～？", 3, "2030/12/17 14:59:59");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (10, 1, 5.0, 24024, "カオリ（サマー）", 0.0, 10021, 24, 0.0, "2019/07/31 12:00:00", 110501, "まだまだ私は元気だよ～！\nマジムンでもなんでも、\nどんとこーいさー♪", 2, "2030/12/17 14:59:59");
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (11, 2, 0.0, 24025, "カオリ（サマー）", 0.0, 10021, 24, 0.0, "2019/07/31 12:00:00", 110501, "私の空手は世界最強さ～！\n夏の陽射しと青い海も合わされば、\n向かうところ敵なしだよー！", 2, "2030/12/17 14:59:59");
